class Solution:
    def maxValue(self, n: int, index: int, maxSum: int) -> int:
        def check(n, index, maxSum, x):
            y = max(x-index, 0)
            total = (x+y)*(x-y+1)//2
            y = max(x-((n-1)-index), 0)
            total += (x+y)*(x-y+1)//2
            return total-x <= maxSum

        maxSum -= n
        left, right = 0, maxSum
        while left <= right:
            mid = left + (right-left)//2
            if not check(n, index, maxSum, mid):
                right = mid-1
            else:
                left = mid+1
        return 1+right

class Solution:
    def countPairs(self, nums, low, high):
        return self._countPairs(nums, high + 1) - self._countPairs(nums, low)

    def _countPairs(self, nums, high):
        res = 0
        for k in range(31, -1, -1):
            target = high >> k
            if target & 1 == 0:
                continue
            target -= 1
            counter = Counter(num >> k for num in nums)
            for mask in counter:
                res += counter[mask] * counter[target ^ mask]
                if mask == target ^ mask:
                    res -= counter[mask]
        return res // 2

